package ru.folio.notes;

import java.util.*;

/** Ordered closed-contour matching: translation, scale, rotation, winding and starting point are free. */
final class ShapeTemplates {
    static final int N=64;
    static final class Template {final String kind;final ArrayList<Ink.Pt> contour;final float[] x=new float[N],y=new float[N];final float norm,length;Template(String kind,List<Ink.Pt> points,float aspect){this.kind=kind;ArrayList<Ink.Pt> p=new ArrayList<>();float[] box=ShapeRecognizer.bounds(points);float cx=(box[0]+box[2])/2,cy=(box[1]+box[3])/2;for(Ink.Pt q:points)p.add(ShapeRecognizer.pt((q.x-cx)*aspect,q.y-cy));contour=p;ArrayList<Ink.Pt> sampled=ShapeRecognizer.resample(p,N+1);float mx=0,my=0;for(int i=0;i<N;i++){mx+=sampled.get(i).x;my+=sampled.get(i).y;}mx/=N;my/=N;float sum=0;for(int i=0;i<N;i++){x[i]=sampled.get(i).x-mx;y[i]=sampled.get(i).y-my;sum+=x[i]*x[i]+y[i]*y[i];}norm=sum;length=ShapeRecognizer.length(p);}}
    static final class Match {String kind;ArrayList<Ink.Pt> points;float score;Match(String kind,ArrayList<Ink.Pt> points,float score){this.kind=kind;this.points=points;this.score=score;}}
    static final ArrayList<Template> TEMPLATES=new ArrayList<>();
    static void add(String kind,List<Ink.Pt> points){for(float aspect:new float[]{.65f,.8f,1,1.25f,1.55f})TEMPLATES.add(new Template(kind,points,aspect));}
    static ArrayList<Ink.Pt> star(int rays,float inner,boolean crossing){ArrayList<Ink.Pt> p=new ArrayList<>();int n=crossing?rays:rays*2;for(int i=0;i<=n;i++){float a=(float)(-Math.PI/2+(crossing?i*4:i)*Math.PI/rays),r=crossing||i%2==0?1:inner;p.add(ShapeRecognizer.pt(r*(float)Math.cos(a),r*(float)Math.sin(a)));}return p;}
    static ArrayList<Ink.Pt> heart(){ArrayList<Ink.Pt> p=new ArrayList<>();for(int i=0;i<=160;i++){double t=i*Math.PI*2/160,x=16*Math.pow(Math.sin(t),3),y=-(13*Math.cos(t)-5*Math.cos(2*t)-2*Math.cos(3*t)-Math.cos(4*t));p.add(ShapeRecognizer.pt((float)x/16,(float)y/16));}return p;}
    static ArrayList<Ink.Pt> puffs(int lobes,float depth){ArrayList<Ink.Pt> p=new ArrayList<>();for(int i=0;i<=192;i++){double a=i*Math.PI*2/192,r=1+depth*Math.cos(lobes*a);p.add(ShapeRecognizer.pt((float)(r*Math.cos(a)),(float)(r*Math.sin(a))));}return p;}
    static void cubic(ArrayList<Ink.Pt> p,float ax,float ay,float bx,float by,float cx,float cy){Ink.Pt start=p.get(p.size()-1);for(int i=1;i<=24;i++){float t=i/24f,u=1-t;p.add(ShapeRecognizer.pt(u*u*u*start.x+3*u*u*t*ax+3*u*t*t*bx+t*t*t*cx,u*u*u*start.y+3*u*u*t*ay+3*u*t*t*by+t*t*t*cy));}}
    static ArrayList<Ink.Pt> cloud(){ArrayList<Ink.Pt> p=new ArrayList<>();p.add(ShapeRecognizer.pt(-.75f,.45f));cubic(p,-1.18f,.45f,-1.2f,-.15f,-.8f,-.22f);cubic(p,-.9f,-.7f,-.35f,-.92f,-.12f,-.55f);cubic(p,.05f,-1.04f,.72f,-.92f,.75f,-.34f);cubic(p,1.22f,-.42f,1.35f,.35f,.86f,.46f);cubic(p,.45f,.55f,-.25f,.52f,-.75f,.45f);return p;}
    static {add("heart",heart());add("cloud",cloud());for(int n=3;n<=8;n++){add("cloud",puffs(n,.12f));add("cloud",puffs(n,.20f));}for(int n=4;n<=8;n++)for(float inner:new float[]{.42f,.55f})add("star",star(n,inner,false));add("star",star(5,1,true));}
    static Match fit(List<Ink.Pt> input,float diagonal,float deficit,float path){if(deficit<.012f)return null;ArrayList<Ink.Pt> p=new ArrayList<>(input);if(ShapeRecognizer.area(p)<0)Collections.reverse(p);if(Ink.dist(p.get(0).x,p.get(0).y,p.get(p.size()-1).x,p.get(p.size()-1).y)>.0001)p.add(p.get(0));p=ShapeRecognizer.resample(p,N+1);float mx=0,my=0;for(int i=0;i<N;i++){mx+=p.get(i).x;my+=p.get(i).y;}mx/=N;my/=N;float[] x=new float[N],y=new float[N];float norm=0;for(int i=0;i<N;i++){x[i]=p.get(i).x-mx;y[i]=p.get(i).y-my;norm+=x[i]*x[i]+y[i]*y[i];}float best=Float.MAX_VALUE;Template winner=null;int bestShift=0;float bestA=0,bestB=0;
        for(Template template:TEMPLATES){if(template.kind.equals("heart")&&deficit<.045||template.kind.equals("star")&&deficit<.12||template.kind.equals("cloud")&&deficit>.28)continue;boolean reverse=ShapeRecognizer.area(template.contour)<0;for(int shift=0;shift<N;shift++){float dot=0,cross=0;for(int i=0;i<N;i++){int j=reverse?(shift-i+N)%N:(i+shift)%N;dot+=template.x[j]*x[i]+template.y[j]*y[i];cross+=template.x[j]*y[i]-template.y[j]*x[i];}float a=dot/template.norm,b=cross/template.norm,scale=(float)Math.hypot(a,b),ratio=path/(template.length*scale);if(ratio<.78f||ratio>1.25f)continue;float error=Math.max(0,norm-(dot*dot+cross*cross)/template.norm),score=(float)Math.sqrt(error/N)/diagonal;if(score<best){best=score;winner=template;bestShift=shift;bestA=a;bestB=b;}}}
        if(winner==null||best>.047f)return null;ArrayList<Ink.Pt> transformed=new ArrayList<>();ArrayList<Ink.Pt> centred=ShapeRecognizer.resample(winner.contour,N+1);float cx=0,cy=0;for(int i=0;i<N;i++){cx+=centred.get(i).x;cy+=centred.get(i).y;}cx/=N;cy/=N;float maximum=0;boolean reverse=ShapeRecognizer.area(winner.contour)<0;for(int i=0;i<N;i++){int j=reverse?(bestShift-i+N)%N:(i+bestShift)%N;float tx=mx+bestA*winner.x[j]-bestB*winner.y[j],ty=my+bestB*winner.x[j]+bestA*winner.y[j];maximum=Math.max(maximum,Ink.dist(tx,ty,p.get(i).x,p.get(i).y));}if(maximum/diagonal>.14f)return null;for(Ink.Pt q:winner.contour){float xx=q.x-cx,yy=q.y-cy;transformed.add(ShapeRecognizer.pt(mx+bestA*xx-bestB*yy,my+bestB*xx+bestA*yy));}return new Match(winner.kind,transformed,best);
    }
}
